from fastapi import FastAPI, Header, BackgroundTasks, Depends, HTTPException
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float

def verify_api_key(x_api_key: str = Header(...)):
    if x_api_key != "secret":
        raise HTTPException(status_code=403, detail="Invalid API Key")
    return x_api_key

@app.post("/items/{item_id}")
async def create_item(item_id: int, item: Item, q: str = None, background_tasks: BackgroundTasks = BackgroundTasks(), api_key: str = Depends(verify_api_key)):
    background_tasks.add_task(lambda: print(f"Item created: {item_id}"))
    return {"item_id": item_id, "q": q, "item": item}
